CREATE TABLE IF NOT EXISTS `assetUsers` (`id` int AUTO_INCREMENT PRIMARY KEY, `employeeCode` varchar(60) NOT NULL UNIQUE, `fullName` varchar(180) NOT NULL, `email` varchar(320), `phone` varchar(40), `departmentId` int, `position` varchar(160), `role` enum('operator','manager','viewer') NOT NULL DEFAULT 'operator', `active` int NOT NULL DEFAULT 1, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `assetAllocations` (`id` int AUTO_INCREMENT PRIMARY KEY, `allocationCode` varchar(80) NOT NULL UNIQUE, `assetId` int NOT NULL, `userId` int NOT NULL, `departmentId` int, `locationId` int, `allocatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `returnedAt` timestamp NULL, `status` enum('active','returned','cancelled') NOT NULL DEFAULT 'active', `note` text);
CREATE TABLE IF NOT EXISTS `attachmentFiles` (`id` int AUTO_INCREMENT PRIMARY KEY, `fileName` varchar(255) NOT NULL, `mimeType` varchar(160) NOT NULL, `size` int NOT NULL, `storagePath` text NOT NULL, `entityType` varchar(80) NOT NULL, `entityId` int, `uploadedById` int, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `systemSettings` (`id` int AUTO_INCREMENT PRIMARY KEY, `settingKey` varchar(120) NOT NULL UNIQUE, `settingValue` text, `description` varchar(255), `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `permissionRules` (`id` int AUTO_INCREMENT PRIMARY KEY, `role` varchar(60) NOT NULL, `module` varchar(80) NOT NULL, `canView` int NOT NULL DEFAULT 0, `canCreate` int NOT NULL DEFAULT 0, `canEdit` int NOT NULL DEFAULT 0, `canDelete` int NOT NULL DEFAULT 0);
